key.harness:
`timescale 1ns/1ps
// The grading testbench.

// Written so that a design which does nothing cannot score well by
// accident. The first draft had five of its seven checks expecting
// zero, so `assign q = 0;` — a module with no register in it at all —
// passed five of them. Every check below now expects a value that only
// a working counter produces, except the two that are about becoming
// zero, and those are paired with a check of the value just before.
module tb;
  logic clk = 1'b0, rst = 1'b1, en = 1'b0;
  logic [3:0] q;
  logic [1:0] q2;
  logic rst2 = 1'b1, en2 = 1'b0;

  counter #(.N(4)) dut (.clk(clk), .rst(rst),  .en(en),  .q(q));
  counter #(.N(2)) two (.clk(clk), .rst(rst2), .en(en2), .q(q2));

  always #5 clk = ~clk;

  initial begin
    @(posedge clk); @(negedge clk);
    $display("CHECK reset 0 %0d AT %0d", q, $time);

    rst = 1'b0; en = 1'b1;
    repeat (3) @(posedge clk); @(negedge clk);
    $display("CHECK counted 3 %0d AT %0d", q, $time);

    en = 1'b0;
    repeat (2) @(posedge clk); @(negedge clk);
    $display("CHECK held 3 %0d AT %0d", q, $time);

    // Twelve more enabled edges reach 15, the top of a four-bit
    // counter. A design that does not count fails here.
    en = 1'b1;
    repeat (12) @(posedge clk); @(negedge clk);
    $display("CHECK at_top 15 %0d AT %0d", q, $time);

    // And the next one wraps to zero rather than saturating at 15.
    @(posedge clk); @(negedge clk);
    $display("CHECK wraps 0 %0d AT %0d", q, $time);

    // Reset wins over enable on the same edge. Counted to a non-zero
    // value first, so "it was already zero" cannot pass this.
    repeat (3) @(posedge clk); @(negedge clk);
    rst = 1'b1;
    @(posedge clk); @(negedge clk);
    $display("CHECK reset_beats_enable 0 %0d AT %0d", q, $time);

    // Synchronous: a reset raised and lowered entirely between two
    // edges has no effect. Counted to 5 first, so the check is that a
    // non-zero value SURVIVES rather than that zero stays zero.
    rst = 1'b0; en = 1'b1;
    repeat (5) @(posedge clk); @(negedge clk);
    en = 1'b0;
    #1 rst = 1'b1;
    #1 rst = 1'b0;      // up and down with no clock edge in between
    #1;
    $display("CHECK sync_reset 5 %0d AT %0d", q, $time);

    // A two-bit instance counts modulo 4: three edges give 3, not 3
    // of a wider count and not 0.
    rst2 = 1'b0; en2 = 1'b1;
    repeat (3) @(posedge clk); @(negedge clk);
    $display("CHECK narrow 3 %0d AT %0d", q2, $time);

    $display("DONE 8");
    $finish;
  end
endmodule

reference.sv:
module counter #(parameter int N = 4) (
  input  logic         clk,
  input  logic         rst,
  input  logic         en,
  output logic [N-1:0] q
);

  always_ff @(posedge clk) begin
    if (rst)     q <= '0;
    else if (en) q <= q + 1'b1;
  end

endmodule
